{
  "name": "@different-ai/opencode-browser",
  "version": "4.6.1",
  "description": "Browser automation plugin for OpenCode (native messaging + per-tab ownership).",
  "type": "module",
  "bin": {
    "opencode-browser": "bin/cli.js"
  },
  "main": "./dist/plugin.js",
  "exports": {
    ".": "./dist/plugin.js",
    "./plugin": "./dist/plugin.js"
  },
  "files": [
    ".opencode",
    "bin",
    "dist",
    "extension",
    "README.md"
  ],
  "scripts": {
    "build": "bun build src/plugin.ts --target=node --outfile=dist/plugin.js",
    "build:cws": "node build-cws-package.mjs",
    "check:extension": "node --check extension/background.js",
    "prepublishOnly": "bun run build",
    "publish": "node -e \"if (process.env.npm_command === 'publish') process.exit(0); require('child_process').execSync('npm publish --access public', { stdio: 'inherit' });\"",
    "install": "node bin/cli.js install",
    "uninstall": "node bin/cli.js uninstall",
    "status": "node bin/cli.js status",
    "tools": "node bin/cli.js tools",
    "self-test": "node bin/cli.js self-test",
    "tool-test": "bun bin/tool-test.ts"
  },
  "keywords": [
    "opencode",
    "browser",
    "automation",
    "chrome",
    "plugin",
    "native-messaging"
  ],
  "author": "Benjamin Shafii",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/different-ai/opencode-browser.git"
  },
  "bugs": {
    "url": "https://github.com/different-ai/opencode-browser/issues"
  },
  "homepage": "https://github.com/different-ai/opencode-browser#readme",
  "peerDependencies": {
    "@opencode-ai/plugin": "*"
  },
  "dependencies": {
    "agent-browser": "^0.4.0"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "*",
    "bun-types": "*"
  }
}
